@staticmethod
def color_adjust(data: Dict[str, Any], endpoints: List[str], adjustment: Dict[str, int]) -> str:
    """
    Adjust color properties of one or more light devices relative to their current settings.

    Args:
        data: The data dictionary containing devices
        endpoints: List of device endpoint IDs to adjust
        adjustment: Dictionary containing relative adjustments to make to color properties
                    (hue: -360 to 360, saturation: -100 to 100, brightness: -100 to 100)

    Returns:
        A JSON string with the result of the operation
    """
    if not endpoints:
        return json.dumps({
            "success": False,
            "message": "No devices specified"
        })

    if not adjustment:
        return json.dumps({
            "success": False,
            "message": "No adjustment specified"
        })

    # Validate adjustment values
    valid_keys = ["hue", "saturation", "brightness"]
    if not any(k in adjustment for k in valid_keys):
        return json.dumps({
            "success": False,
            "message": f"Adjustment must include at least one of: {', '.join(valid_keys)}"
        })

    # Get the current user's home ID
    home_id = get_user_home_id(data)

    results = []
    for endpoint in endpoints:
        device = find_device_by_endpoint(data, endpoint, home_id)
        if device and "color_adjust" in device["supported_apis"]:
            # In a real implementation, this would convert the current color to HSB,
            # apply the adjustments, and convert back to the appropriate format

            # For demonstration purposes, we'll just record the adjustment
            for i, d in enumerate(data["devices"]):
                if d["endpoint"] == endpoint and (home_id is None or d["home_id"] == home_id):
                    if "state" not in data["devices"][i]:
                        data["devices"][i]["state"] = {}

                    # Apply relative adjustments to existing values or create defaults
                    current_state = data["devices"][i]["state"]
                    for key, delta in adjustment.items():
                        if key not in current_state:
                            # Default values if not previously set
                            if key == "hue":
                                current_state[key] = 0
                            elif key in ["saturation", "brightness"]:
                                current_state[key] = 100

                        # Apply the adjustment
                        current_state[key] += delta

                        # Normalize values to valid ranges
                        if key == "hue":
                            current_state[key] = current_state[key] % 360
                        elif key in ["saturation", "brightness"]:
                            current_state[key] = max(0, min(100, current_state[key]))

                    success = True
                    break
            else:
                success = False

            if success:
                results.append({
                    "endpoint": endpoint,
                    "name": device["name"],
                    "success": True,
                    "message": f"Adjusted {device['name']} color properties",
                    "adjustment": adjustment
                })
            else:
                results.append({
                    "endpoint": endpoint,
                    "success": False,
                    "message": f"Failed to update state for device with endpoint {endpoint}"
                })
        else:
            results.append({
                "endpoint": endpoint,
                "success": False,
                "message": f"Device with endpoint {endpoint} not found or does not support color adjustment"
            })

    return json.dumps({
        "success": any(result["success"] for result in results),
        "results": results
    })

@staticmethod
def color_scene(data: Dict[str, Any], scene_name: str, room_id: Optional[str] = None) -> str:
    """
    Apply a predefined color scene to all compatible lights in a room or the entire home.

    Args:
        data: The data dictionary containing devices
        scene_name: Name of the predefined scene to apply (e.g., "movie", "reading", "party")
        room_id: Optional room ID to limit the scene to a specific room. If None, applies to all rooms.

    Returns:
        A JSON string with the result of the operation
    """
    # Predefined scenes with their color configurations
    scenes = {
        "movie": {"primary": "#2B1B81", "accent": "#7B68EE", "brightness": 30},
        "reading": {"primary": "#FFD580", "brightness": 80},
        "party": {"colors": ["#FF0000", "#00FF00", "#0000FF", "#FFFF00", "#FF00FF"], "mode": "cycle", "speed": "medium"},
        "relax": {"primary": "#FF9933", "brightness": 50},
        "energize": {"primary": "#FFFFFF", "brightness": 100, "temperature": 6500}
    }

    if scene_name not in scenes:
        return json.dumps({
            "success": False,
            "message": f"Unknown scene: {scene_name}. Available scenes: {', '.join(scenes.keys())}"
        })

    # Get the current user's home ID
    home_id = get_user_home_id(data)

    # Find all compatible light devices in the specified room or entire home
    compatible_devices = []
    for device in data["devices"]:
        if device["home_id"] == home_id and "color_set" in device.get("supported_apis", []):
            if room_id is None or device.get("room_id") == room_id:
                compatible_devices.append(device)

    if not compatible_devices:
        return json.dumps({
            "success": False,
            "message": f"No compatible light devices found in {'the specified room' if room_id else 'your home'}"
        })

    # Apply the scene to all compatible devices
    scene_config = scenes[scene_name]
    results = []

    for device in compatible_devices:
        # In a real implementation, this would handle different scene types and device capabilities
        # For demonstration purposes, we'll just apply the primary color if available

        for i, d in enumerate(data["devices"]):
            if d["endpoint"] == device["endpoint"]:
                if "state" not in data["devices"][i]:
                    data["devices"][i]["state"] = {}

                # Apply scene properties
                if "primary" in scene_config:
                    data["devices"][i]["state"]["color"] = scene_config["primary"]

                if "brightness" in scene_config:
                    data["devices"][i]["state"]["brightness"] = scene_config["brightness"]

                if "temperature" in scene_config:
                    data["devices"][i]["state"]["temperature"] = scene_config["temperature"]

                if "mode" in scene_config:
                    data["devices"][i]["state"]["mode"] = scene_config["mode"]

                    if "colors" in scene_config:
                        data["devices"][i]["state"]["colors"] = scene_config["colors"]

                    if "speed" in scene_config:
                        data["devices"][i]["state"]["speed"] = scene_config["speed"]

                results.append({
                    "endpoint": device["endpoint"],
                    "name": device["name"],
                    "success": True,
                    "message": f"Applied '{scene_name}' scene to {device['name']}"
                })
                break

    return json.dumps({
        "success": len(results) > 0,
        "scene": scene_name,
        "room": room_id if room_id else "all rooms",
        "results": results
    })
```

